import java.util.regex.Pattern;
import java.util.regex.Matcher;

public class ValidarTelefono {
    public static void main(String[] args) {
        String telefono1 = "123-456-7890";
        String telefono2 = "1234567890";
        String telefono3 = "12-456-7890";

        Pattern patron = Pattern.compile("\\d{3}-\\d{3}-\\d{4}");
        boolean isValido1 = patron.matcher(telefono1).matches();
        boolean isValido2 = patron.matcher(telefono2).matches();
        boolean isValido3 = patron.matcher(telefono3).matches();
        System.out.println(telefono1 + " => " + isValido1);
        System.out.println(telefono2 + " => " + isValido2);
        System.out.println(telefono3 + " => " + isValido3);
    }
}

